"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def integerSqrt(n):
    if (n < 2):
        return n
    low = 1
    high = n
    ans = 0
    while (low <= high):
        mid = ((low + high) // 2)
        square = (mid * mid)
        if (square == n):
            return mid
        elif (square < n):
            ans = mid
            low = (mid + 1)
        else:
            high = (mid - 1)
    return ans
print(integerSqrt(10))